    [Fact]
    public void WebhookVerification()
    {
        Assert.Equal(
            Vectors.Root.GetProperty("webhook_verification").GetProperty("default_tolerance_seconds").GetDouble(),
            TungoWebhooks.DefaultTolerance.TotalSeconds);
        Vectors.ForEach(Vectors.Cases("webhook_verification", "cases"), item =>
        {
            var expect = item.GetProperty("expect");
            TimeSpan? tolerance = item.TryGetProperty("tolerance_seconds", out var seconds) ? TimeSpan.FromSeconds(seconds.GetDouble()) : null;
            var now = DateTimeOffset.FromUnixTimeSeconds(item.GetProperty("now").GetInt64());
            var secret = Vectors.OptionalString(item, "secret") ?? string.Empty;
            var body = item.GetProperty("body").GetString()!;
            if (expect.GetProperty("valid").GetBoolean())
            {
                var webhookEvent = TungoWebhooks.Verify(body, Vectors.Headers(item), secret, tolerance, now);
                Assert.Equal(expect.GetProperty("event_type").GetString(), webhookEvent.Type);

                // Only the deliberately incomplete vector may fall back to the unknown variant.
                if (!item.TryGetProperty("contract_valid", out var contractValid) || contractValid.GetBoolean())
                {
                    Assert.False(webhookEvent.IsUnknown, "a contract-valid event was decoded as unknown");
                }

                // The same delivery through the byte and the multi-valued overloads.
                var multi = Vectors.Headers(item).ToDictionary(header => header.Key, header => new[] { header.Value });
                Assert.Equal(webhookEvent.Type, TungoWebhooks.Verify(Encoding.UTF8.GetBytes(body), multi, secret, tolerance, now).Type);
            }
            else
            {
                var error = Assert.Throws<TungoWebhookVerificationException>(() => TungoWebhooks.Verify(body, Vectors.Headers(item), secret, tolerance, now));
                Assert.Equal(expect.GetProperty("reason").GetString(), SnakeCase(error.Reason.ToString()));
            }
        });
    }

