    [Fact]
    public void Errors()
    {
        Vectors.ForEach(Vectors.Cases("errors", "cases"), item =>
        {
            var expect = item.GetProperty("expect");
            var error = TungoApiException.Create(item.GetProperty("status").GetInt32(), item.GetProperty("body").GetString()!, Vectors.Headers(item));
            Assert.Equal(item.GetProperty("status").GetInt32(), error.StatusCode);
            Assert.Equal(expect.GetProperty("envelope").GetBoolean(), error.IsEnvelope);
            Assert.Equal(ErrorClass(expect.GetProperty("class").GetString()!), error.GetType().Name);
            Assert.Equal(expect.GetProperty("type").GetString(), error.Type);
            Assert.Equal(Vectors.OptionalString(expect, "code"), error.Code);
            Assert.Equal(Vectors.OptionalString(expect, "request_id"), error.RequestId);
            if (error.IsEnvelope)
            {
                Assert.Equal(expect.GetProperty("message").GetString(), error.ApiMessage);
                Assert.Contains(error.ApiMessage!, error.Message, StringComparison.Ordinal);
            }

            var retryAfter = expect.TryGetProperty("retry_after", out var seconds) && seconds.ValueKind == JsonValueKind.Number ? seconds.GetDouble() : (double?)null;
            Assert.Equal(retryAfter, error.RetryAfter?.TotalSeconds);

            var fields = expect.TryGetProperty("fields", out var list) && list.ValueKind == JsonValueKind.Array ? list.EnumerateArray().ToArray() : Array.Empty<JsonElement>();
            Assert.Equal(fields.Length, error.Fields.Count);
            for (var i = 0; i < fields.Length; i++)
            {
                Assert.Equal(fields[i].GetProperty("path").GetString(), error.Fields[i].Path);
                Assert.Equal(fields[i].GetProperty("code").GetString(), error.Fields[i].Code.Value);
                Assert.Equal(fields[i].GetProperty("message").GetString(), error.Fields[i].Message);
            }

            AssertExtra(expect, error);
        });
    }

