    [Fact]
    public async Task RetryAfterDecidesWhetherTheClientSleeps()
    {
        await Vectors.ForEachAsync(Vectors.Cases("retry_after", "cases"), async item =>
        {
            var now = DateTimeOffset.Parse(item.GetProperty("now").GetString()!, CultureInfo.InvariantCulture);
            var expect = item.GetProperty("expect");
            var headers = Vectors.Headers(item).Select(header => (header.Key, header.Value)).ToArray();
            var handler = new StubHandler()
                .Json(Sdk.ErrorJson("limit_error", "slow down"), 429, headers)
                .Json(Sdk.CompanyJson);
            var delays = new List<TimeSpan>();
            using var client = Sdk.Client(handler, options => options.Clock = () => now, delays);
            if (expect.GetProperty("sleep").GetBoolean())
            {
                await client.Companies.GetAsync();
                Assert.Equal(2, handler.Requests.Count);
                var delay = Assert.Single(delays);
                if (expect.GetProperty("seconds").ValueKind == JsonValueKind.Number && expect.GetProperty("seconds").GetDouble() > 0)
                {
                    Assert.Equal(expect.GetProperty("seconds").GetDouble(), delay.TotalSeconds, 3);
                }
                else
                {
                    // No usable value, zero or a date in the past: the computed backoff, never an immediate retry.
                    Assert.Equal(RetryPolicy.BackoffSeconds(0, 0.0), delay.TotalSeconds, 3);
                }
            }
            else
            {
                await Assert.ThrowsAsync<TungoLimitException>(() => client.Companies.GetAsync());
                Assert.Single(handler.Requests);
                Assert.Empty(delays);
            }
        });
    }

    [Fact]
    public async Task ZeroOrPastRetryAfterUsesTheComputedBackoff()
    {
        var now = new DateTimeOffset(2026, 11, 9, 15, 0, 0, TimeSpan.Zero);
        var cases = new (string Name, string Value)[]
        {
            ("Retry-After", "0"),
            ("Retry-After", "0.0"),
            ("retry-after-ms", "0"),
            ("Retry-After", "Mon, 09 Nov 2026 14:59:00 GMT"),
            ("Retry-After", "Mon, 09 Nov 2026 15:00:00 GMT"),
        };
        foreach (var header in cases)
        {
            var handler = new StubHandler()
                .Json(Sdk.ErrorJson("limit_error", "slow down"), 429, header)
                .Json(Sdk.CompanyJson);
            var delays = new List<TimeSpan>();
            using var client = Sdk.Client(handler, options => options.Clock = () => now, delays);
            await client.Companies.GetAsync();
            var delay = Assert.Single(delays);
            Assert.True(delay > TimeSpan.Zero, header.Name + ": " + header.Value + " must not retry at once");
            Assert.Equal(RetryPolicy.BackoffSeconds(0, 0.0), delay.TotalSeconds, 3);
        }
    }

    [Fact]
    public void Backoff()
    {
        var section = Vectors.Root.GetProperty("backoff");
        Vectors.ForEach(Vectors.Cases("backoff", "cases"), item =>
        {
            var attempt = item.GetProperty("attempt").GetInt32();
            var min = item.GetProperty("expect").GetProperty("min_seconds").GetDouble();
            var max = item.GetProperty("expect").GetProperty("max_seconds").GetDouble();
            Assert.Equal(min, RetryPolicy.BackoffSeconds(attempt, 0.0), 9);
            Assert.InRange(RetryPolicy.BackoffSeconds(attempt, 0.5), min, max);
            Assert.InRange(RetryPolicy.BackoffSeconds(attempt, 0.999999), min, max);
            Assert.True(max <= section.GetProperty("max_seconds").GetDouble());
        });
        Assert.Equal(section.GetProperty("base_seconds").GetDouble() * section.GetProperty("jitter_max").GetDouble(), RetryPolicy.BackoffSeconds(0, 1.0), 9);
    }

    [Fact]
    public async Task RetryPolicyDrivesTheTransport()
    {
        await Vectors.ForEachAsync(Vectors.Cases("retry_policy"), async item =>
        {
            var handler = new StubHandler();
            var cause = item.GetProperty("cause");
            if (cause.ValueKind == JsonValueKind.Number)
            {
                handler.Json(Sdk.ErrorJson("api_error", "failed"), cause.GetInt32());
            }
            else if (cause.GetString() == "connection_error")
            {
                handler.Fail(new HttpRequestException("connection refused"));
            }
            else
            {
                Assert.Equal("timeout", cause.GetString());
                handler.Hang();
            }

            handler.Json("{}");
            var options = new TungoClientOptions
            {
                HttpMessageHandler = handler,
                Timeout = TimeSpan.FromMilliseconds(100),
                MaxRetries = 1,
                DelayAsync = (_, _) => Task.CompletedTask,
            };
            using var transport = new TungoTransport(options, Sdk.ApiKey, new Uri("https://api.test"));
            // idempotency_key: the operation declares the header and the request carries a key;
            // caller_key: the caller gives a key to an operation that declares none.
            var declared = item.GetProperty("idempotency_key").GetBoolean();
            var callerKey = Vectors.Flag(item, "caller_key");
            var request = new TungoRequest(new HttpMethod(item.GetProperty("method").GetString()!), "/v1/things", "/v1/things", TungoAuth.ApiKey)
            {
                IdempotencyHeader = declared ? "Idempotency-Key" : null,
            };
            var requestOptions = new RequestOptions
            {
                IdempotencyKey = declared || callerKey ? "key-1" : null,
                Headers = callerKey ? new Dictionary<string, string> { ["Idempotency-Key"] = "key-2" } : null,
            };
            var retried = item.GetProperty("expect").GetProperty("retry").GetBoolean();
            if (retried)
            {
                await transport.SendAsync(request, requestOptions, CancellationToken.None);
            }
            else
            {
                await Assert.ThrowsAnyAsync<TungoException>(() => transport.SendAsync(request, requestOptions, CancellationToken.None));
            }

            Assert.Equal(retried ? 2 : 1, handler.Requests.Count);
            Assert.Equal(declared, handler.Requests[0].Header("Idempotency-Key") is not null);
        });
    }

