    [Fact]
    public void Query()
    {
        Vectors.ForEach(Vectors.Cases("query"), item =>
        {
            var query = new QueryBuilder();
            foreach (var parameter in item.GetProperty("params").EnumerateArray())
            {
                var name = parameter.GetProperty("name").GetString()!;
                var value = parameter.GetProperty("value");
                if (value.ValueKind == JsonValueKind.Null)
                {
                    query.Add(name, (string?)null);
                    continue;
                }

                switch (parameter.GetProperty("type").GetString())
                {
                    case "string":
                        query.Add(name, value.GetString());
                        break;
                    case "boolean":
                        query.Add(name, (bool?)value.GetBoolean());
                        break;
                    case "integer":
                        query.Add(name, (long?)(value.ValueKind == JsonValueKind.String ? long.Parse(value.GetString()!, CultureInfo.InvariantCulture) : value.GetInt64()));
                        break;
                    case "date-time":
                        query.Add(name, (DateTimeOffset?)DateTimeOffset.Parse(value.GetString()!, CultureInfo.InvariantCulture));
                        break;
                    case "array":
                        query.Add(name, value.EnumerateArray().Select(element => element.GetString()!));
                        break;
                    default:
                        throw new InvalidOperationException("unknown parameter type " + parameter.GetProperty("type").GetString());
                }
            }

            var expect = item.GetProperty("expect");
            if (expect.TryGetProperty("any_of", out var anyOf))
            {
                Assert.Contains(query.ToString(), anyOf.EnumerateArray().Select(option => option.GetString()));
            }
            else
            {
                Assert.Equal(expect.GetProperty("query").GetString(), query.ToString());
            }
        });
    }

    [Fact]
    public void Sse()
    {
        Vectors.ForEach(Vectors.Cases("sse"), item =>
        {
            var raw = Convert.FromBase64String(item.GetProperty("raw_base64").GetString()!);
            var expected = item.GetProperty("expect").GetProperty("events").EnumerateArray().ToArray();

            // As one chunk, byte by byte, and in the chunks the case prescribes.
            var splits = new List<IReadOnlyList<byte[]>> { new[] { raw }, raw.Select(one => new[] { one }).ToArray() };
            if (item.TryGetProperty("chunks_base64", out var chunks))
            {
                splits.Add(chunks.EnumerateArray().Select(chunk => Convert.FromBase64String(chunk.GetString()!)).ToArray());
            }

            foreach (var split in splits)
            {
                var parser = new SseParser();
                var events = new List<SseEvent>();
                foreach (var chunk in split)
                {
                    parser.Feed(chunk, 0, chunk.Length, events);
                }

                Assert.Equal(expected.Length, events.Count);
                for (var i = 0; i < expected.Length; i++)
                {
                    Assert.Equal(expected[i].GetProperty("event").GetString(), events[i].Event);
                    Assert.Equal(expected[i].GetProperty("data").GetString(), events[i].Data);
                    Assert.Equal(Vectors.OptionalString(expected[i], "id"), events[i].Id);
                    if (expected[i].TryGetProperty("retry", out var retry))
                    {
                        Assert.Equal(retry.ValueKind == JsonValueKind.Number ? retry.GetInt32() : (int?)null, events[i].Retry);
                    }
                }
            }
        });
    }

    [Fact]
    public void SseHandlesVeryLongLines()
    {
        // 8 MB of data in one line, fed in 64 KiB chunks.
        var line = new byte[(8 * 1024 * 1024) + 6];
        Array.Fill(line, (byte)'x');
        Encoding.ASCII.GetBytes("data: ").CopyTo(line, 0);
        var parser = new SseParser();
        var events = new List<SseEvent>();
        for (var offset = 0; offset < line.Length; offset += 65536)
        {
            parser.Feed(line, offset, Math.Min(65536, line.Length - offset), events);
        }

        parser.Feed(new[] { (byte)'\n', (byte)'\n' }, 0, 2, events);
        Assert.Equal(8 * 1024 * 1024, Assert.Single(events).Data.Length);
    }

