    [Fact]
    public async Task ChatStream()
    {
        // A turn repeated with the same Idempotency-Key after it finished is answered with its stored JSON result
        // (chat_stream_replay): the stream must yield the same turn as the vector expects.
        var cases = Vectors.Cases("chat_stream")
            .Concat(Vectors.Cases("chat_stream_replay").Where(item => !Vectors.Flag(item.GetProperty("expect"), "decode_error")))
            .ToList();
        await Vectors.ForEachAsync(cases, async item =>
        {
            var expect = item.GetProperty("expect");
            var headers = Vectors.Headers(item).Select(header => (header.Key, header.Value)).ToArray();
            var handler = new StubHandler();
            if (item.TryGetProperty("raw", out var rawElement))
            {
                var raw = rawElement.GetString()!;
                handler.Sse(raw, headers).Sse(raw, headers);
            }
            else
            {
                var body = item.GetProperty("body").GetRawText();
                var status = item.GetProperty("status").GetInt32();
                handler.Json(body, status, headers).Json(body, status, headers);
            }

            using var client = Sdk.Client(handler);
            var accumulator = new ChatAccumulator();
            var stream = client.Chat.CreateStreamAsync(new ChatMessageRequest { Message = "question" });
            await foreach (var chatEvent in stream)
            {
                accumulator.Add(chatEvent);
            }

            var turn = accumulator.ToChatTurn(stream.Response);
            Assert.Equal(Vectors.OptionalString(expect, "dialog_id"), turn.DialogId);
            Assert.Equal(expect.GetProperty("turn_no").ValueKind == JsonValueKind.Number ? expect.GetProperty("turn_no").GetInt64() : (long?)null, turn.TurnNo);
            Assert.Equal(expect.GetProperty("text").GetString(), turn.Text);
            Assert.Equal(Vectors.OptionalString(expect, "stop_reason"), turn.StopReason);
            Assert.Equal(expect.GetProperty("event_count").GetInt32(), turn.Events.Count);
            Assert.Equal(expect.GetProperty("cost_tiyn").ValueKind == JsonValueKind.Number ? expect.GetProperty("cost_tiyn").GetInt64() : (long?)null, turn.CostTiyn);
            Assert.Equal(Vectors.OptionalString(expect, "choice_id"), turn.ChoiceId);
            if (expect.GetProperty("usage").ValueKind == JsonValueKind.Object)
            {
                Assert.NotNull(turn.Usage);
                Assert.Equal(expect.GetProperty("usage").GetProperty("input_tokens").GetInt64(), turn.Usage.InputTokens);
                Assert.Equal(expect.GetProperty("usage").GetProperty("output_tokens").GetInt64(), turn.Usage.OutputTokens);
                Assert.Equal(expect.GetProperty("usage").GetProperty("cache_read_tokens").GetInt64(), turn.Usage.CacheReadTokens);
                Assert.Equal(expect.GetProperty("usage").GetProperty("cache_write_tokens").GetInt64(), turn.Usage.CacheWriteTokens);
            }
            else
            {
                Assert.Null(turn.Usage);
            }

            if (expect.TryGetProperty("event_types", out var types))
            {
                Assert.Equal(types.EnumerateArray().Select(type => type.GetString()), turn.Events.Select(chatEvent => chatEvent.Type));
            }

            // The helper reads the whole stream and raises the error event as the typed exception.
            var helper = client.Chat.CreateStreamAsync(new ChatMessageRequest { Message = "question" });
            if (expect.GetProperty("error").ValueKind == JsonValueKind.Object)
            {
                var expectedError = expect.GetProperty("error");
                var error = accumulator.Error;
                Assert.NotNull(error);
                var thrown = await Assert.ThrowsAnyAsync<TungoApiException>(() => helper.ToChatTurnAsync());
                foreach (var candidate in new[] { error, thrown })
                {
                    Assert.Equal(expectedError.GetProperty("type").GetString(), candidate.Type);
                    Assert.Equal(ErrorClass(candidate.Type), candidate.GetType().Name);
                    Assert.Equal(Vectors.OptionalString(expectedError, "code"), candidate.Code);
                    Assert.Equal(expectedError.GetProperty("message").GetString(), candidate.ApiMessage);
                    Assert.Equal(Vectors.OptionalString(expectedError, "request_id"), candidate.RequestId);
                    AssertExtra(expectedError, candidate);
                }
            }
            else if (!accumulator.IsDone)
            {
                // The stream ended without its final event: the accumulated text is not a finished turn.
                Assert.Null(accumulator.Error);
                var cut = await Assert.ThrowsAsync<TungoDecodeException>(() => helper.ToChatTurnAsync());
                Assert.Equal(turn.Text, cut.Body);
            }
            else
            {
                Assert.Null(accumulator.Error);
                Assert.Equal(turn.Text, (await helper.ToChatTurnAsync()).Text);
            }
        });
    }

    private static void AssertExtra(JsonElement expect, TungoApiException error)
    {
        var extra = expect.TryGetProperty("extra", out var value) && value.ValueKind == JsonValueKind.Object ? value.EnumerateObject().ToArray() : Array.Empty<JsonProperty>();
        Assert.Equal(extra.Select(property => property.Name).OrderBy(name => name, StringComparer.Ordinal), error.Extra.Keys.OrderBy(name => name, StringComparer.Ordinal));
        foreach (var property in extra)
        {
            Assert.True(
                JsonNode.DeepEquals(JsonNode.Parse(property.Value.GetRawText()), JsonNode.Parse(error.Extra[property.Name].GetRawText())),
                "extra." + property.Name + " differs: " + error.Extra[property.Name].GetRawText());
        }
    }

    private static string ErrorClass(string kind)
    {
        if (kind == "api_error")
        {
            return nameof(TungoServerException);
        }

        var name = new StringBuilder("Tungo");
        foreach (var word in kind.Substring(0, kind.Length - "_error".Length).Split('_'))
        {
            name.Append(char.ToUpperInvariant(word[0])).Append(word, 1, word.Length - 1);
        }

        return name.Append("Exception").ToString();
    }

    private static string SnakeCase(string pascal)
    {
        var text = new StringBuilder();
        foreach (var c in pascal)
        {
            if (char.IsUpper(c) && text.Length > 0)
            {
                text.Append('_');
            }

            text.Append(char.ToLowerInvariant(c));
        }

        return text.ToString();
    }
}
